using System;
using System.Collections.Generic;
using Astrea.BattleActions;
using Astrea.GameElements;
using LittleLeo;
using LittleLeo.Events;
using UnityEngine;
using UnityEngine.EventSystems;

namespace Astrea.GameStates;

[CreateAssetMenu(fileName = "OnMouseOverDiceTargetCastState", menuName = "Data/Battle/Actions/OnMouseOverDiceTargetCastState")]
public class OnMouseOverDiceTargetCastState : Action
{
	[Header("Events")]
	[SerializeField]
	private VoidEvent OnSetTransitionOutlineLayerYellowHighlightColor;

	[NonSerialized]
	private GameObject previouslyRaycastResult;

	public void OnReset()
	{
		previouslyRaycastResult = null;
	}

	public override void OnStartState()
	{
		base.OnStartState();
		OnReset();
	}

	public override void Execute(float d)
	{
		List<RaycastResult> uIObjectsOverMouse = MouseInputUtility.GetUIObjectsOverMouse();
		GameObject gameObject = null;
		if (uIObjectsOverMouse.Count > 0)
		{
			RaycastResult raycastResult = uIObjectsOverMouse.First();
			DiceInstance componentInParent = raycastResult.gameObject.GetComponentInParent<DiceInstance>();
			if (componentInParent != null)
			{
				ChooseDiceAction obj = componentInParent.ChooseDiceActionInstanceReference.Value.ActionFace.BattleAction as ChooseDiceAction;
				DiceActionLogic_ChooseDice diceActionLogic_ChooseDice = obj.GetDiceActionLogic(componentInParent.ChooseDiceActionInstanceReference.Value.ActionFace.ModifiedActionValue) as DiceActionLogic_ChooseDice;
				if (obj.CheckCondition(componentInParent) && componentInParent.CheckPointAndClickDraggableStates(diceActionLogic_ChooseDice.ChooseDicesState, playCantUseActionFeedback: false))
				{
					gameObject = componentInParent.gameObject;
				}
			}
			DicePlacement componentInChildren = raycastResult.gameObject.GetComponentInChildren<DicePlacement>();
			if (componentInChildren != null)
			{
				gameObject = componentInChildren.gameObject;
			}
		}
		if (gameObject != null && previouslyRaycastResult == null)
		{
			OnMouseOver();
			previouslyRaycastResult = gameObject;
		}
		if (previouslyRaycastResult != null && previouslyRaycastResult != gameObject)
		{
			OnMouseExit();
			previouslyRaycastResult = null;
		}
	}

	private void OnMouseOver()
	{
		if (!(base.actionInstance == null))
		{
			if (base.actionInstance is DiceInstance)
			{
				OnSetTransitionOutlineLayerYellowHighlightColor.Raise();
			}
			else
			{
				(base.actionInstance as RuneInstance).HighlightRuneInstance();
			}
		}
	}

	private void OnMouseExit()
	{
		if (!(base.actionInstance == null))
		{
			if (base.actionInstance is DiceInstance)
			{
				(base.actionInstance as DiceInstance).UpdateTransitionOutlineLayer();
			}
			else
			{
				(base.actionInstance as RuneInstance).RemoveHighlightRuneInstance();
			}
		}
	}
}
